import { useState, type FormEvent } from 'react'
import { useQuery } from '@tanstack/react-query'
import { clusterNameQuery, setClusterName } from '../../api/resources/overview'
import { useApiMutation } from '../../components/mutation'
import { PageHeader } from '../../components/PageHeader'
import { Section } from '../../components/Section'
import { ErrorMessage, Loading } from '../../components/Status'

export function ClusterNamePage() {
  const current = useQuery(clusterNameQuery())
  const header = <PageHeader kind="Cluster name" title={current.data?.name ?? ''} documentTitle="Cluster name" />
  if (!current.data) return <>{header}{current.error ? <ErrorMessage error={current.error} what="the cluster name" /> : <Loading />}</>
  return (
    <>
      {header}
      <div className="callout">
        <p style={{ marginTop: 0 }}>
          The cluster name can be used by clients to identify clusters over AMQP connections, and is used by the shovel and federation plugins to
          identify which clusters a message has been routed through.
        </p>
        <p>
          Note that the cluster name is announced to clients in the AMQP server properties, before authentication has taken place. Therefore it
          should not be considered secret.
        </p>
        <p style={{ marginBottom: 0 }}>The cluster name is generated by default from the name of the first node in the cluster, but can be changed.</p>
      </div>
      <Section id="cluster-name-change" title="Change name">
        <ChangeName initial={current.data.name} />
      </Section>
    </>
  )
}

function ChangeName({ initial }: { initial: string }) {
  const [name, setName] = useState(initial)
  // The header shows the name from the start-up overview, so that is refreshed too.
  const change = useApiMutation({ mutationFn: () => setClusterName(name), success: 'Cluster name changed', invalidate: [['cluster-name'], ['overview']] })
  const submit = (event: FormEvent) => {
    event.preventDefault()
    change.mutate()
  }
  return (
    <form className="form" onSubmit={submit}>
      <label htmlFor="cluster-name-input">Name</label>
      <input id="cluster-name-input" type="text" required value={name} onChange={(e) => setName(e.target.value)} data-testid="cluster-name-input" />
      <div className="actions">
        <button type="submit" className="btn btn-primary" disabled={change.isPending} data-testid="cluster-name-submit">
          Change name
        </button>
      </div>
    </form>
  )
}
